const TOOLS = [
  {
    name: 'ticket_create',
    description: 'Create a support ticket with a title, description, and optional priority.',
    inputSchema: {
      type: 'object',
      properties: {
        title: { type: 'string', description: 'Short title for the ticket.' },
        description: { type: 'string', description: 'Detailed description of the issue.' },
        priority: {
          type: 'string',
          enum: ['low', 'normal', 'high'],
          description: 'Priority level for the ticket.',
        },
      },
      required: ['title', 'description'],
      additionalProperties: false,
    },
  },
];

const ALLOWED_PRIORITIES = new Set(['low', 'normal', 'high']);
const toolsByName = new Map(TOOLS.map((t) => [t.name, t]));
let nextId = 1;

function asObject(args) {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object.');
  }
  return args;
}

function isNonEmptyString(value) {
  return typeof value === 'string' && value.length > 0;
}

function validateTicketCreate(args) {
  const obj = asObject(args);
  const keys = Object.keys(obj);
  const allowed = new Set(['title', 'description', 'priority']);
  for (const key of keys) {
    if (!allowed.has(key)) {
      throw new Error(`Invalid arguments: unknown field "${key}".`);
    }
  }
  if (!isNonEmptyString(obj.title)) {
    throw new Error('Invalid arguments: "title" must be a non-empty string.');
  }
  if (!isNonEmptyString(obj.description)) {
    throw new Error('Invalid arguments: "description" must be a non-empty string.');
  }
  const priority = obj.priority ?? 'normal';
  if (!ALLOWED_PRIORITIES.has(priority)) {
    throw new Error('Invalid arguments: "priority" must be one of low, normal, high.');
  }
  return { title: obj.title, description: obj.description, priority };
}

export async function listTools() {
  return TOOLS;
}

export async function callTool(name, args) {
  const tool = toolsByName.get(name);
  if (!tool) {
    throw new Error(`Unknown tool: ${name}`);
  }
  if (name === 'ticket_create') {
    const input = validateTicketCreate(args);
    const id = `t${nextId++}`;
    const text = `Created ticket ${id} [${input.priority}]: ${input.title}`;
    return { content: [{ type: 'text', text }] };
  }
  throw new Error(`Unknown tool: ${name}`);
}

